source='''from collections import deque

def components(grid, color):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        q.append(p)
            result.append(cells)
    return result

def shape(cells):
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    return frozenset((r-r0, c-c0) for r, c in cells)

def transform(grid):
    out = [row[:] for row in grid]
    refs = {}
    for color in range(2, 10):
        for cells in components(grid, color):
            refs.setdefault(shape(cells), color)
    for cells in components(grid, 1):
        color = refs.get(shape(cells))
        if color is not None:
            for r, c in cells:
                out[r][c] = color
    return out
